// slice 41 — TWO DIGITS, and the digits are written most-significant-LAST, so
// the buffer's length has to be known before it is taken. The eleventh class
// reaches `%FE#11@#x`, which is the shape anonymous_parameter_name already had
// to get right for `__10`; sharing the reason is why this fixture exists at all.
//
// ★ It also pins the counter ACROSS ten classes: an off-by-one anywhere in the
// draw shows up here as `#10` or `#12` on a class whose position in the file is
// plain to read.

class C1 {
    #x = 1;
}

class C2 {
    #x = 2;
}

class C3 {
    #x = 3;
}

class C4 {
    #x = 4;
}

class C5 {
    #x = 5;
}

class C6 {
    #x = 6;
}

class C7 {
    #x = 7;
}

class C8 {
    #x = 8;
}

class C9 {
    #x = 9;
}

class C10 {
    #x = 10;
}

class C11 {
    #x = 11;
}
